/* Student geometry is part of the compiled precinct atlas. No duplicate runtime surfaces. */
(function(root){const api={prepare(data,nav){const b=data.buildings.find(b=>b.id==='167607356');b.library17=true;b.student22=true;b.h=19.05;}};if(typeof module==='object')module.exports=api;else root.Student22=api;})(this);
function buildStudent22(B,scene,c){const groups=new Map(),mats={},pt=(x,z)=>[c.origin[0]+c.u[0]*x+c.v[0]*z,c.origin[1]+c.u[1]*x+c.v[1]*z];for(const[n,col]of Object.entries({ivory:'#dedfd6',glass:'#527782',frame:'#3b555c',wood:'#a5713e',roof:'#68736c'})){const m=new B.StandardMaterial('student22-'+n,scene);m.diffuseColor=B.Color3.FromHexString(col);m.specularColor=B.Color3.Black();mats[n]=m;}
function box(n,x,z,w,d,y,h,mat){const p=pt(x+w/2,z+d/2),m=B.MeshBuilder.CreateBox(n,{width:w,depth:d,height:h},scene);m.position.set(p[0],c.base+y+h/2,p[1]);m.rotation.y=-Math.atan2(c.u[1],c.u[0]);m.material=mats[mat];if(!groups.has(mat))groups.set(mat,[]);groups.get(mat).push(m);}
for(let x=-32.7;x<-1;x+=10.6){const w=Math.min(9.7,-x-.5);box('head-upper-window',x,.08,w,.12,12.2,4.6,'glass');for(let j=0;j<w;j+=2.4)box('head-window-mullion',x+j,.18,.09,.12,12.2,4.6,'frame');for(const y of[13.75,15.25])box('head-transom',x,.18,w,.12,y,.09,'frame');}
for(let z=-45;z<-1;z+=10){const d=Math.min(9,-z-.5);box('east-upper-window',-33.8,z,.12,d,12.2,4.6,'glass');box('east-mid-window',-33.8,z,.12,d,8.9,2.2,'glass');for(const y of[13.75,15.25])box('east-transom',-33.9,z,.12,d,y,.09,'frame');}
for(let z=.7;z<36;z+=8.8)for(const[y,h]of[[.8,2.3],[4.8,2.5],[8.7,2.5],[12.5,2.5]]){const d=Math.min(8.1,37-z);box('wing-window',-.12,z,.12,d,y,h,'glass');for(let k=2;k<d;k+=2)box('wing-mullion',-.22,z+k,.12,.09,y,h,'frame');}
for(let x=-32.7;x<-28;x+=.42)box('corner-louver',x,.25,.12,.4,.2,7.8,'wood');
// Thin independent eaves preserve the original polygon outline.
for(const [poly,y]of[[c.head,19.05],[c.wing,16.45]])for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],len=Math.hypot(b[0]-a[0],b[1]-a[1]),m=B.MeshBuilder.CreateBox('student22-eave',{width:len+.3,height:.22,depth:.7},scene);m.position.set((a[0]+b[0])/2,c.base+y+.11,(a[1]+b[1])/2);m.rotation.y=-Math.atan2(b[1]-a[1],b[0]-a[0]);if(!groups.has('roof'))groups.set('roof',[]);groups.get('roof').push(m);}
for(const x of[-21.3,-9])for(let i=0;i<26;i++)box('entry-sidewall',x,18-(i+1)*17/26,.3,17/26,4.3*(i+1)/26,.55,'ivory');
for(const[mat,list]of groups){const m=B.Mesh.MergeMeshes(list,true,true);m.name='building-167607356-student22-'+mat;m.material=mats[mat];m.metadata={facilityId:'167607356'};m.receiveShadows=true;m.freezeWorldMatrix();}}
